import React, { useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import AppShell from './AppShell';
import { predictHealthScore } from '../services/api';

const fields = [
  { name: 'sleep', label: 'Sleep', placeholder: 'Hours of sleep', hint: 'Example: 7.5' },
  { name: 'water', label: 'Water', placeholder: 'Liters of water', hint: 'Example: 2.5' },
  { name: 'exercise', label: 'Exercise', placeholder: 'Minutes exercised', hint: 'Example: 45' },
  { name: 'calories', label: 'Calories', placeholder: 'Calories consumed', hint: 'Example: 2100' },
];

export default function Predict() {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({ sleep: '', water: '', exercise: '', calories: '' });
  const [score, setScore] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const handleChange = (event) => {
    const { name, value } = event.target;
    setFormData((current) => ({ ...current, [name]: value }));
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    setLoading(true);
    setError('');
    setSuccess('');

    try {
      const payload = {
        sleep: Number(formData.sleep),
        water: Number(formData.water),
        exercise: Number(formData.exercise),
        calories: Number(formData.calories),
      };
      const response = await predictHealthScore(payload);
      setScore(response.score);
      setSuccess('Prediction completed successfully.');
    } catch (submitError) {
      if (submitError.message === 'Missing authentication token') {
        navigate('/login');
        return;
      }
      setError(submitError.message || 'Failed to fetch data');
    } finally {
      setLoading(false);
    }
  };

  const scoreLabel = useMemo(() => {
    if (score === null) return 'No data available';
    if (score >= 80) return 'Excellent';
    if (score >= 60) return 'Good';
    if (score >= 40) return 'Needs improvement';
    return 'Low';
  }, [score]);

  return (
    <AppShell
      title="Predict Health Score"
      subtitle="Your backend converts sleep, water, exercise, and calories into a score using your ML model."
      actions={<button type="button" className="ghost-btn" onClick={() => navigate('/dashboard')}>Back to Dashboard</button>}
    >
      <div className="detail-grid">
        <section className="panel-card">
          <h3>Daily Health Inputs</h3>
          <p>Fill out the four model features in the same order used by your Flask prediction API.</p>

          <form className="stack" onSubmit={handleSubmit} style={{ marginTop: '20px' }}>
            {fields.map((field) => (
              <div className="field" key={field.name}>
                <label htmlFor={field.name}>{field.label}</label>
                <input
                  id={field.name}
                  type="number"
                  name={field.name}
                  step="any"
                  placeholder={field.placeholder}
                  value={formData[field.name]}
                  onChange={handleChange}
                  required
                />
                <span className="hint">{field.hint}</span>
              </div>
            ))}

            <button className="primary-btn" type="submit" disabled={loading}>
              {loading ? 'Loading...' : 'Generate Score'}
            </button>

            <span className={`status-text ${error ? 'error-text' : success ? 'success-text' : ''}`}>
              {error || success || 'No data available'}
            </span>
          </form>
        </section>

        <aside className="stack">
          <section className="panel-card">
            <div className="card-icon icon-orange">?</div>
            <p className="hint">Predicted score</p>
            <div className="result-score">{score !== null ? Number(score).toFixed(2) : '--'}</div>
            <p className="stat-label">{scoreLabel}</p>
          </section>

          <section className="panel-card">
            <h3>Model Feature Order</h3>
            <div className="metric-list">
              <div className="metric-item"><span>1. Sleep</span><strong>{formData.sleep || '--'}</strong></div>
              <div className="metric-item"><span>2. Water</span><strong>{formData.water || '--'}</strong></div>
              <div className="metric-item"><span>3. Exercise</span><strong>{formData.exercise || '--'}</strong></div>
              <div className="metric-item"><span>4. Calories</span><strong>{formData.calories || '--'}</strong></div>
            </div>
          </section>
        </aside>
      </div>
    </AppShell>
  );
}
